        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "«Colpa di Ben Gvir». Flotilla, Tajani assolve Netanyahu e gli altri",
        "testo_it": "Il ministro Tajani attribuisce a Ben Gvir la colpa dell'attacco alla Flotilla, difendendo Netanyahu.",
        "priorita": "Alta",
        "id_gruppo": 25,
        "link": "https://ilmanifesto.it/colpa-di-ben-gvir-flotilla-tajani-assolve-netanyahu-e-gli-altri",
        "orario": "00:06",
